test('duplicate compares amounts in cents: 4.35 and 4.350', () =>
  withTrip(async ({ call }) => {
    const raw = '{"entries":[{"type":"expense","description":"Taxi","payer":"Ann","amount":4.35},'
      + '{"type":"expense","description":"Taxi","payer":"Ann","amount":4.350}]}'
    const res = await call('POST', '/groups/trip/import', raw)
    assert.equal(res.status, 422)
    assert.deepEqual(res.body, rejected(DUP_1))
  }))

