test('already-recorded: description differs by case and whitespace', () =>
  withTrip(async ({ call }) => {
    await record(call)
    for (const description of [' hotel ', 'HOTEL']) {
      await expectProblems(call, [expense({ description })], [{ index: 0, rule: 'already-recorded' }])
    }
  }))

